@* Displays a single task card with move buttons *@

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>

    <div class="task-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move btn-move-left" @onclick="OnMoveLeftClicked">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move btn-move-right" @onclick="OnMoveRightClicked">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClicked() => await OnMoveLeft.InvokeAsync(Task);
    private async System.Threading.Tasks.Task OnMoveRightClicked() => await OnMoveRight.InvokeAsync(Task);
}

@* Inline form to create a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" class="form-input" />
    <input type="text" placeholder="Assignee" @bind="assignee" class="form-input" />
    <select @bind="priority" class="form-input">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" class="form-input" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<NewTaskModel> OnSave { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        await OnSave.InvokeAsync(new NewTaskModel(title, assignee, priority, dueDate));

        // Reset form
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }

    private async Task Cancel() => await OnCancel.InvokeAsync();

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@* A single Kanban column with header, task cards, and add-task button/form *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title <span class="column-count">(@Tasks.Count)</span></h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>

    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm OnSave="HandleSave" OnCancel="HandleCancel" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string Title { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showForm = false;
    }

    private void HandleCancel() => showForm = false;
}

@* Search bar for filtering tasks by title *@

<div class="board-search-bar">
    <input type="text"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput"
           class="search-input" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   TodoCount="GetTasksForStatus("To Do").Count"
                   InProgressCount="GetTasksForStatus("In Progress").Count"
                   DoneCount="GetTasksForStatus("Done").Count"
                   OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="GetFilteredTasksForStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="@(task => MoveTask(task, "In Progress"))"
                      OnAddTask="@(model => AddTask(model, "To Do"))" />

        <KanbanColumn Title="In Progress"
                      Tasks="GetFilteredTasksForStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="@(task => MoveTask(task, "To Do"))"
                      OnMoveRight="@(task => MoveTask(task, "Done"))"
                      OnAddTask="@(model => AddTask(model, "In Progress"))" />

        <KanbanColumn Title="Done"
                      Tasks="GetFilteredTasksForStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@(task => MoveTask(task, "In Progress"))"
                      OnAddTask="@(model => AddTask(model, "Done"))" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForStatus(string status)
        => allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForStatus(string status)
        => allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchText)
                || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Update local state
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            // CreateTaskAsync returns the task; ensure it has the correct status
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

